def best_overlap(a,b):
    # max over relative shifts of matching cells minus mismatch? use Jaccard-like: max |intersect| / |union|
    best=0
    Ha,Wa=len(a),len(a[0]); Hb,Wb=len(b),len(b[0])
    A={(y,x) for y in range(Ha) for x in range(Wa) if a[y][x]}
    B={(y,x) for y in range(Hb) for x in range(Wb) if b[y][x]}
    for dy in range(-Hb,Ha):
